import fs from "node:fs";
import {buildReview} from "./review-adversarial-r7-20261102.mjs";
import {collectAuthoredMetadata} from "./bank.mjs";
import {specs} from "./adversarial-r7-specs-20261102.mjs";
const b=await buildReview(),metadata=collectAuthoredMetadata(b.content);
const fallbacks=JSON.parse(fs.readFileSync("docs/research/question-batch1-round7-fallbacks-20261102.json","utf8")).items;
const sequence=JSON.parse(fs.readFileSync("tools/question-quality/adversarial-r7-sequence-audit-20261102.json","utf8"));
const cell=s=>String(s??"not recorded").replaceAll("|","\\|").replaceAll("\n"," ");
const claimIds=[...new Set(b.content.QUESTION_QUALITY_ADVERSARIAL_R7_REVISIONS.flatMap(r=>r.question.supportingEvidenceClaimIds))].sort();
const claims=claimIds.map(id=>metadata.claims.get(id));
const sourceIds=[...new Set(claims.flatMap(c=>c.sourceIds))].sort();
const sources=sourceIds.map(id=>metadata.sources.get(id));
const sourceLines=["# Sources and atomic-claim mappings for the final authoring round","","Recorded 2026-11-03. No network access, new article retrieval, source-text storage or source-prose copying occurred. All medical publications below were previously verified in this thread. Original access dates, citation metadata, authority and rights limitations are retained. A new mapping ID is not another independent publication.","",`The eleven rewritten versions map ${claims.length} existing/new atomic claims to ${sources.length} source records. Two new limited application claims reuse three fully recorded primary sources; all new clinical records remain needs_clinician_review. The remaining 62 PASS versions retain their earlier source ledgers and exact clinical records.`,"","The B18 1.8-mm value is retained from the same case's existing completed-primary record, and 0.6 mm from its prior partial-report draft. Their new cross-specimen placement is constructed and needs dermatopathology review. Neither is a treatment threshold. The actual greater-than-1-mm discussion boundary uses the pre-existing nodal-staging claim and its verified guideline/independent source. No new probability, dose, elapsed-time rule or demographic weight is authored.","","The B19 claim is a technical application of current MRI characterization guidance to different acquisition settings. One adequate medical primary consensus source is recorded; there was no new independent verification of the exact sequence pair. It requires MSK radiology confirmation. The QI table is visibly constructed, uses the same ten simulated visit records per workflow and establishes neither causal benefit nor a rollout gate.","","## Atomic claims",""];
for(const c of claims){sourceLines.push("### "+c.id,"",c.statement,"","- Supporting source IDs: "+c.sourceIds.join(", "),"- Evidence category / certainty: "+c.evidenceCategory+" / "+c.certainty,"- Limitation: "+c.limitation,"- Last checked / clinical status: "+c.lastCheckedOn+" / "+c.reviewStatus,"");}
sourceLines.push("## Source records","","Full metadata is also retained in the source modules. License permission and medical authority are separate assessments. Undated records remain n.d.; no year is inferred from the access date.","");
for(const s of sources){sourceLines.push("### "+s.id,"","- Full citation: "+(s.completeCitation??s.title),"- Organization / journal: "+(s.organizationOrJournal??s.organization??s.journal??s.publisher??"See complete citation"),"- Authors: "+(Array.isArray(s.authors)?s.authors.join("; "):s.authors??"See complete citation; organizational author where stated"),"- Publication year: "+(s.publicationYear??"n.d."),"- DOI / official URL: "+[s.doi,s.officialUrl].filter(Boolean).join("; "),"- Access date: "+s.accessedOn,"- Source class: "+s.sourceClass,"- License / reuse: "+[s.licenseLabel,s.reuseStatus,s.reuseNotes].filter(Boolean).join("; "),"- Medical authority: "+s.authorityAssessment,"- Intended evidence / cross-check use: "+(s.usageRole??s.intendedUse??s.intendedEvidenceUse??s.evidenceUse??"Targeted factual support/cross-check for the mapped atomic claims; no source text reused"),"- Supported evidence-claim IDs in this round: "+claims.filter(c=>c.sourceIds.includes(s.id)).map(c=>c.id).join(", "),"");}
fs.writeFileSync("docs/research/sources-question-adversarial-r7-20261102.md",sourceLines.join("\n"));
const lines=["# Final authoring-round responses to independent review six","","Recorded 2026-11-03. Exactly eleven REVISE versions are replaced; 62 PASS versions, B01/B10/B29 and eleven exact Melissa Rowland approvals remain frozen. All new versions remain needs_clinician_review. This is an author response, not independent PASS or clinical approval. No basic exemption is introduced.","","Both review packets show the key first for review only; runtime choices remain randomized. Every review-six cue, fairness and suggestion note has an indexed response. The 107 returned-item notes are below; all 225 packet notes have responses/preservation records in the regenerated JSON.","","[Exact original fallbacks](question-batch1-round7-fallbacks-20261102.json) are references for the manager if review seven still returns an item. No later owner-reviewed/shipped draft is verified for these eleven batch items; the original is used rather than an unverified author revision. No fallback is applied. Do not rewind whole cases, change frozen PASS companions or transfer their approvals/histories.",""];
for(const review of b.entry.review.filter(r=>specs.has(r.id))){const s=specs.get(review.id),p=b.all.find(p=>p.id===review.id),f=fallbacks.find(f=>f.id===review.id);lines.push("## "+review.id+" — "+p.title,"","- Reviewed before: "+p.before.variantId,"- New draft: "+p.after.variantId,"- Original fallback: "+f.variantId+" ("+f.conceptId+")","- Change: "+s.change,"- Intended inference: "+s.steps.join(" Then "),"- Deciding observation: "+s.decisive,"- Closest credible error: "+s.closest,"- Cue/deletion attack: "+s.attack,"- Predicted difficulty: "+s.difficulty+"; not a measured or independent finding.","- Clinical limitation: "+s.risk,"- Version decision: "+(s.concept?s.concept.reason:"Clinical meaning retained; new wording/structure receives a new variant version."),"");
 for(const k of ["cues","fairness","suggestions"]){lines.push("| Review-six "+k+" note | Specific response |","| --- | --- |");review[k].forEach((note,i)=>lines.push("| "+cell((i+1)+". "+(typeof note==="string"?note:note.phrase+" — "+note.why))+" | "+cell(s.responses[k][i])+" |"));lines.push("");}}
lines.push("## Eight preceding-feedback checks","","A frozen later node does not make its visible sequence unchanged. These dispositions use actual runtime order, including feedback; no carried rating is described as a fresh sequence assessment.","","| Later PASS item | Disposition |","| --- | --- |");
for(const r of sequence.rows)lines.push("| "+r.id+" | "+cell(r.response)+" |");
lines.push("","B21/B22's earlier context items are also PASS and explicitly frozen in this round. Their residual learner-text/scaffold caveats are preserved for manager direction; repairing them here would violate the supplied freeze. B19's returned precursor is changed in both its scored task and feedback, rather than hiding only the explanation.","");
fs.writeFileSync("docs/research/question-adversarial-round7-response-20261102.md",lines.join("\n"));
console.log(JSON.stringify({items:11,returnedNoteResponses:107,sequenceAudits:8,fallbacks:fallbacks.length,claims:claims.length,sources:sources.length}));
